-- =============================================================================
-- Montreal Residential Market Intelligence — seed the data-source registry
--
-- Apply after 001–005:
--   psql "$DATABASE_URL" -f docs/sql/006_seed_data_sources.sql
--
-- Fixes a real bug found the first time this schema met a real server.
--
-- `import_runs.data_source_id` has a foreign key to `data_sources(id)`. The
-- application knows fourteen sources — they live in `data/demo/sources.ts` —
-- but only two of them were ever inserted by a migration. So the very first
-- thing an ingest run does, `startRun()`, failed against a real database:
--
--     insert or update on table "import_runs" violates foreign key constraint
--     "import_runs_data_source_id_fkey"
--
-- Every unit test passed, because the fake SQL executor has no foreign keys.
-- The pipeline would have failed on its first live run, before making a single
-- outbound request, and the failure would have looked like a database problem
-- rather than a missing row.
--
-- Design notes:
--
--  * NON-DESTRUCTIVE. `ON CONFLICT (id) DO NOTHING` — re-applying it changes
--    nothing, and a source whose description was edited in the database is not
--    reverted by re-running the migration.
--
--  * `last_updated` is deliberately NOT set here. It means "when did an import
--    last succeed", and a migration has not imported anything. Setting it would
--    make every source claim to be current on the day the schema was created.
--
--  * `status` is copied from the registry as-is, which means most rows arrive as
--    'planned'. A source that has never connected must not read as active just
--    because a row exists for it.
-- =============================================================================

BEGIN;

INSERT INTO data_sources
  (id, name, source_type, url, status, licence, description, refresh_cadence)
VALUES
  ('src-demo-sales', 'Demo sale statistics', 'demo', '/docs/DATA_PIPELINE.md', 'active', NULL, 'Synthetic resale statistics generated by this repository. Plausible in shape, invented in value. Not a measurement of the Montréal market.', 'monthly'),
  ('src-demo-rentals', 'Demo rental statistics', 'demo', '/docs/DATA_PIPELINE.md', 'active', NULL, 'Synthetic rent and vacancy statistics generated by this repository. Not a measurement of the Montréal rental market.', 'monthly'),
  ('src-cmhc-rms', 'CMHC Rental Market Survey', 'government', 'https://www.cmhc-schl.gc.ca/professionals/housing-markets-data-and-research', 'planned', 'CMHC terms of use — attribution required', 'Average rent, median rent, vacancy and availability rates by bedroom count for Montréal CMA zones. The authoritative Canadian rental series; published annually with a semi-annual update.', 'annual'),
  ('src-cmhc-scss', 'CMHC Starts and Completions Survey', 'government', 'https://www.cmhc-schl.gc.ca/professionals/housing-markets-data-and-research', 'planned', 'CMHC terms of use — attribution required', 'Housing starts, completions and units under construction. Feeds a future supply-pipeline view, which is the missing half of any inventory analysis.', 'monthly'),
  ('src-montreal-open-data', 'Ville de Montréal Open Data', 'open-data', 'https://donnees.montreal.ca/', 'planned', 'Creative Commons Attribution 4.0', 'The portal as a whole: borough boundaries (GeoJSON), the property assessment roll and dwelling counts. Construction permits are tracked separately as their own source, because a source entry that covers a whole portal cannot honestly report whether any one dataset is connected. The boundary dataset is what the market map is waiting on.', 'irregular'),
  ('src-quebec-open-data', 'Données Québec', 'open-data', 'https://www.donneesquebec.ca/', 'planned', 'Open Government Licence — Québec', 'Provincial datasets including the property assessment roll (rôle d''évaluation foncière) and school-board and municipal tax rates used by the affordability calculator.', 'annual'),
  ('src-statcan', 'Statistics Canada', 'government', 'https://www150.statcan.gc.ca/', 'planned', 'Statistics Canada Open Licence', 'Census dwelling and household characteristics, plus the New Housing Price Index. Provides the denominators that turn raw counts into rates.', 'quarterly'),
  ('src-licensed-listings', 'Licensed listing feed', 'licensed', 'https://www.centris.ca/', 'planned', 'Commercial agreement required — redistribution restricted', 'Transaction-level resale data (sale price, days on market, listing-to-sale ratio). Requires a signed data agreement; redistribution terms usually forbid republishing individual records, so only aggregates would be served.', 'daily'),
  ('src-demo-mortgage-rates', 'Demo mortgage rates', 'demo', '/docs/MORTGAGE_RATE_PIPELINE.md', 'active', NULL, 'Synthetic lender rates generated by this repository. The institutions are real; the rates are invented and were never published by any of them. Not a quote.', 'daily'),
  ('src-lender-rate-feed', 'Lender posted-rate feed', 'licensed', 'https://www.ratehub.ca/', 'planned', 'Commercial agreement required — most aggregators forbid redistribution', 'Posted and discounted rates across Canadian lenders. The realistic route to live rates: aggregators already do the collection that scraping lender sites would otherwise require, and they license it.', 'daily'),
  ('src-boc-valet', 'Bank of Canada Valet API', 'government', 'https://www.bankofcanada.ca/valet/docs', 'active', 'Bank of Canada terms of use — open, attribution required', 'Government of Canada benchmark bond yields, the policy rate and conventional mortgage benchmarks. Free, keyless and documented. The 5-year bond yield is ingested as a market benchmark — it is what lenders fund 5-year fixed mortgages against, and it is not itself a mortgage rate.', 'daily'),
  ('src-demo-benchmarks', 'Demo market benchmarks', 'demo', '/docs/BANK_OF_CANADA.md', 'active', NULL, 'A generated stand-in for the Government of Canada bond yield series, used when no database is connected. Deliberately attributed to itself rather than to the Bank of Canada — these numbers were never published by anyone.', 'daily'),
  ('src-montreal-permits', 'Ville de Montréal construction permits', 'open-data', 'https://donnees.montreal.ca/dataset/permis-construction', 'planned', 'Creative Commons Attribution 4.0', 'Construction, renovation and demolition permits issued by the Ville de Montréal, aggregated to borough-month totals. The supply side of a market this platform otherwise describes only through prices and rents. A permit is authorisation to build, not a completed dwelling.', 'monthly'),
  ('src-demo-permits', 'Demo construction permits', 'demo', '/docs/REAL_DATA_PIPELINE.md', 'active', NULL, 'A generated stand-in for the Ville de Montréal permit series, used until the real connector has imported. Deliberately attributed to itself rather than to the city — these counts were never published by anyone.', 'monthly'),
  ('src-derived-metrics', 'Derived market metrics', 'derived', '/docs/DATA_PIPELINE.md', 'active', NULL, 'Metrics this application computes from other sources: months of inventory, market condition score, year-over-year change and the Montréal-wide roll-up.', 'monthly')
ON CONFLICT (id) DO NOTHING;

COMMIT;

-- Verification:
--   SELECT count(*) FROM data_sources;                  -- expect 14
--   SELECT id, status FROM data_sources ORDER BY id;
